-- ใบเช็กลิสต์ยืมของ ห้องผ่าตัด — ตั้งค่าฐานข้อมูล (วางทั้งไฟล์ใน Supabase > SQL Editor แล้วกด Run ครั้งเดียว)
create table if not exists or_store (
  kind text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (kind, id)
);
create index if not exists or_store_kind_time on or_store (kind, updated_at desc);

alter table or_store enable row level security;
drop policy if exists or_store_all on or_store;
create policy or_store_all on or_store for all to anon, authenticated using (true) with check (true);
grant select, insert, update, delete on or_store to anon, authenticated;

-- เคสมาตรฐาน 32 เคส (ไม่ทับของเดิมถ้ารันซ้ำ)
on conflict (kind, id) do nothing;
